+    try {
+      var now = Instant.now().toEpochMilli();
+      renewLeases(now, getLeasesToRenew(now));
+    } catch (InterruptedException | ExecutionException e) {
+      eventHandler.handle(Event.warn(Utils.grpcAwareErrorMessage(e, verboseFailures)));
