+        }
+      } finally {
+        leaseLock.unlock();
+      }
+    } catch (IOException e) {
+      eventHandler.handle(Event.warn(Utils.grpcAwareErrorMessage(e, verboseFailures)));
+    }
+  }
+
+  private void writeLeases() {
